def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    recent_len = 20 if n >= 20 else n
    recent_start = n - recent_len

    recent_opp_d = 0
    recent_unprov = 0
    for i in range(recent_start, n):
        m, o = history[i]
        if o == 'D':
            recent_opp_d += 1
        if m == 'C' and o == 'D':
            recent_unprov += 1

    recent_opp_c = recent_len - recent_opp_d
    recent_opp_d_rate = recent_opp_d / float(recent_len)
    recent_opp_c_rate = recent_opp_c / float(recent_len)

    total_opp_d = 0
    unprov_total = 0
    after_my_d_c = 0
    after_my_d_d = 0
    after_my_c_c = 0
    after_my_c_d = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            total_opp_d += 1
        if m == 'C' and o == 'D':
            unprov_total += 1
        if i + 1 < n:
            nxt = history[i + 1][1]
            if m == 'D':
                if nxt == 'C':
                    after_my_d_c += 1
                else:
                    after_my_d_d += 1
            else:
                if nxt == 'C':
                    after_my_c_c += 1
                else:
                    after_my_c_d += 1

    opp_d_rate = total_opp_d / float(n)

    after_d_total = after_my_d_c + after_my_d_d
    after_c_total = after_my_c_c + after_my_c_d
    forg_rate = after_my_d_c / float(after_d_total) if after_d_total else 0.0
    pun_rate = after_my_c_d / float(after_c_total) if after_c_total else 0.0

    run_opp_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            run_opp_d += 1
        else:
            break

    dd_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    if n >= 10 and after_d_total >= 4 and after_c_total >= 4:
        if forg_rate >= 0.65 and pun_rate >= 0.50:
            return 'D'

    if last_opp == 'C' and last_me == 'D':
        if after_d_total >= 3 and forg_rate >= 0.75 and total_opp_d >= 2 and recent_opp_d_rate >= 0.25:
            return 'D'

    if (
        opp_d_rate >= 0.65
        or recent_opp_d_rate >= 0.65
        or run_opp_d >= 4
        or (unprov_total >= 6 and recent_unprov >= 3 and recent_opp_d_rate >= 0.35)
    ):
        if last_opp == 'C' and last_me == 'D' and recent_opp_d_rate < 0.75 and forg_rate > 0.6:
            return 'C'
        return 'D'

    if n == 85 and total_opp_d == 0 and recent_opp_d == 0:
        return 'D'

    if last_opp == 'C':
        if last_me == 'D':
            if n >= 85 and recent_opp_c_rate >= 0.70 and forg_rate >= 0.70 and after_d_total >= 1:
                return 'D'
            return 'C'
        return 'C'

    if last_me == 'C':
        if (
            recent_opp_c_rate >= 0.80
            and recent_unprov <= 2
            and unprov_total <= 5
            and run_opp_d <= 1
            and total_opp_d <= n * 0.35
        ):
            return 'C'
        return 'D'

    if dd_run >= 3 or recent_opp_d_rate >= 0.50 or unprov_total >= 6:
        return 'D'

    if (
        recent_opp_c_rate >= 0.55
        or (total_opp_d < n * 0.30 and recent_unprov <= 2 and dd_run <= 2)
    ):
        return 'C'

    return 'D'
